-- Movement balances, tenancy constraints, scoped writes and immutable stock history.
select no_plan();
select tests.create_range_fixture();
select is((select stock_qty from public.store_prices where store_id = '90000000-0000-0000-0000-000000000001'),10,'stock is derived from deltas');
select is((select qty_after from public.stock_movements where store_id = '90000000-0000-0000-0000-000000000001'),10,'movement balance ignores supplied snapshot');
select throws_ok($test$insert into public.store_items(organisation_id,store_id,range_item_id) values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002','91000000-0000-0000-0000-000000000001')$test$,'23503',null,'store item cannot cross tenants');
select throws_ok($test$update public.collection_items set organisation_id = '10000000-0000-0000-0000-000000000001' where collection_id = '92000000-0000-0000-0000-000000000002'$test$,'23503',null,'collection item cannot cross tenants');
reset role;
select tests.act_as('organisation_owner');
select lives_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',-2,'manual')$test$,'owner records a manual decrease');
select lives_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',5,'csv','fixture-import')$test$,'owner records a CSV increase');
select is((select stock_qty from public.store_prices where store_id = '90000000-0000-0000-0000-000000000001'),13,'stock is the sum of all movements');
select is((select stock_source from public.store_prices where store_id = '90000000-0000-0000-0000-000000000001'),'csv','stock provenance is latest movement');
select throws_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',-14,'manual')$test$,'23514',null,'negative balance fails atomically');
select is((select count(*) from public.stock_movements),3::bigint,'failed stock write leaves no movement');
select throws_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000002','91000000-0000-0000-0000-000000000002',1,'csv')$test$,'42501',null,'other retailer stock is denied');
select throws_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',1,'till')$test$,'23514',null,'client till attribution is unavailable');
select lives_ok($test$update public.store_items set price_override_minor = 3200 where store_id = '90000000-0000-0000-0000-000000000001'$test$,'owner overrides store price');
select is((select price_minor from public.store_prices where store_id = '90000000-0000-0000-0000-000000000001'),3200::bigint,'store override resolves centrally');
reset role;
update public.memberships set store_ids = array['90000000-0000-0000-0000-000000000001'::uuid] where profile_id = tests.get_supabase_uid('organisation_manager');
select tests.act_as('organisation_manager');
select lives_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',-13,'manual')$test$,'scoped manager changes assigned store');
select is((select status from public.shows where id = '93000000-0000-0000-0000-000000000001'),'stock_issue','exhausted stock marks retailer show');
select lives_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',2,'csv')$test$,'manager replenishes assigned store');
select is((select status from public.shows where id = '93000000-0000-0000-0000-000000000001'),'live','replenishment recovers retailer show');
select is(tests.import_affected_rows($test$update public.range_items set hidden = true$test$),0::bigint,'scoped manager cannot change organisation range');
reset role;
select tests.act_as('supplier_member');
select throws_ok($test$select public.record_stock('90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',1,'csv')$test$,'42501',null,'supplier has no stock management rights');
reset role;
set local role service_role;
select throws_ok('update public.stock_movements set delta = 0','23514',null,'service cannot rewrite stock history');
select throws_ok('delete from public.stock_movements','23514',null,'service cannot delete stock history');
select finish();
